<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | AutoTrack</title><link rel="stylesheet" href="css/style.css"></head><body><div class="auth"><section class="auth-visual"><h1>Smart vehicle maintenance, in one place.</h1><p>Track services, receive SMS maintenance alerts, compare repair estimates, find nearby garages, and get help from the AI maintenance assistant.</p></section><section class="auth-panel"><form class="auth-card" onsubmit="event.preventDefault();location.href='dashboard.html'"><h2>Welcome back</h2><p class="muted">Sign in to your AutoTrack account.</p><div class="field"><label>Email</label><input type="email" value="gobi@example.com" required></div><div class="field"><label>Password</label><input type="password" value="password" required></div><button class="btn btn-primary full-btn">Sign in</button><p class="footer-note">New user? <a href="register.html" style="color:#2563eb">Create an account</a></p></form></section></div></body></html>